import { createFileRoute } from "@tanstack/react-router";
import { z } from "zod";

import { RankingPage } from "#/ranking/components/ranking-page.tsx";
import { getRankingData } from "#/ranking/ranking.functions.ts";

const searchSchema = z.object({
  /** The expanded restaurant's venue slug, so an opened row can be shared. */
  venue: z.string().optional().catch(undefined),
});

export const Route = createFileRoute("/")({
  validateSearch: searchSchema,
  loader: () => getRankingData(),
  component: RankingRoute,
});

function RankingRoute() {
  const data = Route.useLoaderData();
  const { venue } = Route.useSearch();
  const navigate = Route.useNavigate();

  function toggle(slug: string) {
    const next = slug === venue ? undefined : slug;

    void navigate({ search: { venue: next }, replace: true, resetScroll: false });
  }

  return <RankingPage data={data} expandedSlug={venue} onToggle={toggle} />;
}

/**
 * The data the ranking page renders. Every field comes straight from the stored
 * scarcity data, so a loader can return database rows without reshaping them.
 */
import type { collections, restaurantRanking, scarcityScores } from "#/db/schema.ts";
import type { Evidence, Observation } from "#/scarcity/model.ts";

/** A `collections` row, without import bookkeeping. */
export type CollectionSummary = Pick<
  typeof collections.$inferSelect,
  | "id"
  | "startedAt"
  | "finishedAt"
  | "anchorDate"
  | "discoveryComplete"
  | "selection"
  | "limitations"
>;

/** One `scarcity_scores` row: a seven-day band of a restaurant's snapshot. */
export type ScoreBand = typeof scarcityScores.$inferSelect;

/** A `restaurant_ranking` row with the supporting records of the same collection. */
export type RestaurantRecord = typeof restaurantRanking.$inferSelect & {
  /** `restaurant_snapshots.evidence`. */
  evidence: Evidence[];
  /** All `scarcity_scores` bands, in any order. */
  bands: ScoreBand[];
  /** `dinner_observations.detail`, in any order. Dates without a row were not checked. */
  observations: Observation[];
};

export type RankingData = {
  /** Every collection referenced by a restaurant's `collectionId`. */
  collections: CollectionSummary[];
  /** Every `restaurant_ranking` row, in any order. */
  restaurants: RestaurantRecord[];
};

import { createServerFn } from "@tanstack/react-start";

import type { RankingData } from "./contract.ts";
import { sampleRankingData } from "./sample-data.ts";

/**
 * The page's only data source. It serves sample data until it reads the database:
 * return every `restaurant_ranking` row with its collection's snapshot evidence,
 * `scarcity_scores` bands, and `dinner_observations` details (see `RankingData`).
 */
export const getRankingData = createServerFn({ method: "GET" }).handler((): RankingData =>
  sampleRankingData(),
);

import { addDays } from "#/scarcity/model.ts";
import type { Observation } from "#/scarcity/model.ts";

import type { CollectionSummary, RankingData, RestaurantRecord, ScoreBand } from "./contract.ts";

const HORIZON_DAYS = 28;

/** A date without an observation row was not checked; it is never evidence of scarcity. */
export type DayStatus = Observation["status"] | "missing";

export type Slot = Extract<Observation, { status: "available" }>["slots"][number];

export type CalendarDay = {
  /** Days after the snapshot's SF date, 1–28. */
  offset: number;
  diningDate: string;
  status: DayStatus;
  slots: Slot[];
};

export type Opening = { diningDate: string; slot: Slot };

/** Standard competition ranking: equal scores share a position, and the next one skips. */
export type Rank = { position: number; tied: boolean };

type EntryBase = {
  restaurant: RestaurantRecord;
  slug: string;
  /** Bands ordered by start day; the first is the headline week. */
  bands: ScoreBand[];
  days: CalendarDay[];
  observed: boolean;
  nextOpening: Opening | null;
};

export type RankedEntry = EntryBase & { standing: "ranked"; score: number; rank: Rank };

export type UnrankedStanding = "unscored" | "unresolved" | "excluded";

export type UnrankedEntry = EntryBase & { standing: UnrankedStanding; reason: string };

export type RestaurantEntry = RankedEntry | UnrankedEntry;

export type Ranking = {
  collections: CollectionSummary[];
  ranked: RankedEntry[];
  /** Venues without a comparable score, grouped in display order. Empty groups are omitted. */
  unranked: { standing: UnrankedStanding; entries: UnrankedEntry[] }[];
  venueCount: number;
};

const UNRANKED_ORDER: UnrankedStanding[] = ["unscored", "unresolved", "excluded"];

export function buildRanking(data: RankingData): Ranking {
  const scored: { base: EntryBase; score: number }[] = [];
  const unranked = new Map<UnrankedStanding, UnrankedEntry[]>();

  for (const restaurant of data.restaurants) {
    const base = entryBase(restaurant);

    if (restaurant.eligibility === "eligible" && restaurant.score !== null) {
      scored.push({ base, score: restaurant.score });
      continue;
    }

    const entry = unrankedEntry(base);
    const group = unranked.get(entry.standing) ?? [];
    group.push(entry);
    unranked.set(entry.standing, group);
  }

  // Ties stay ties; names only make their display order stable.
  const byScore = scored.toSorted((a, b) => b.score - a.score || byName(a.base, b.base));

  const ranked: RankedEntry[] = [];

  for (const [index, { base, score }] of byScore.entries()) {
    const previous = ranked.at(-1);
    const position = previous?.score === score ? previous.rank.position : index + 1;
    const tied = previous?.score === score || byScore[index + 1]?.score === score;

    ranked.push({ ...base, standing: "ranked", score, rank: { position, tied } });
  }

  return {
    collections: data.collections,
    ranked,
    unranked: UNRANKED_ORDER.flatMap((standing) => {
      const entries = unranked.get(standing);

      if (!entries) {
        return [];
      }

      return [{ standing, entries: entries.toSorted(byName) }];
    }),
    venueCount: data.restaurants.length,
  };
}

function byName(a: { restaurant: RestaurantRecord }, b: { restaurant: RestaurantRecord }) {
  return a.restaurant.name.localeCompare(b.restaurant.name);
}

function entryBase(restaurant: RestaurantRecord): EntryBase {
  const days = dinnerCalendar(restaurant);

  return {
    restaurant,
    slug: venueSlug(restaurant.resyUrl),
    bands: restaurant.bands.toSorted((a, b) => a.startDay - b.startDay),
    days,
    observed: restaurant.observations.length > 0,
    nextOpening: firstOpening(days),
  };
}

function unrankedEntry(base: EntryBase): UnrankedEntry {
  const { restaurant } = base;

  if (restaurant.eligibility !== "eligible") {
    return { ...base, standing: restaurant.eligibility, reason: restaurant.eligibilityReason };
  }

  const headline = base.bands.find((band) => band.startDay === 1);
  const gap = headline ? bandGap(headline) : null;
  const reason = gap ?? restaurant.scoreReason ?? "Headline week is incomplete";

  return { ...base, standing: "unscored", reason };
}

function dinnerCalendar(restaurant: RestaurantRecord): CalendarDay[] {
  const byDate = new Map(restaurant.observations.map((item) => [item.diningDate, item]));

  return Array.from({ length: HORIZON_DAYS }, (_, index) => {
    const offset = index + 1;
    const diningDate = addDays(restaurant.anchorDate, offset);
    const observation = byDate.get(diningDate);

    if (!observation) {
      return { offset, diningDate, status: "missing", slots: [] };
    }

    const slots = observation.status === "available" ? observation.slots : [];

    return { offset, diningDate, status: observation.status, slots };
  });
}

function firstOpening(days: CalendarDay[]): Opening | null {
  for (const day of days) {
    const [earliest] = day.slots.toSorted((a, b) => a.time.localeCompare(b.time));

    if (earliest) {
      return { diningDate: day.diningDate, slot: earliest };
    }
  }

  return null;
}

/** Why a band has no score, stated from its coverage counts. Null when the band is scored. */
export function bandGap(band: ScoreBand): string | null {
  if (band.score !== null) {
    return null;
  }

  const gaps: [number, string][] = [
    [band.unreleased, "not released"],
    [band.unknown, "unclear"],
    [band.collectionError, "failed"],
    [band.missing, "not checked"],
  ];

  const parts: string[] = [];

  for (const [count, label] of gaps) {
    if (count > 0) {
      parts.push(`${count} ${label}`);
    }
  }

  if (parts.length > 0) {
    return parts.join(" · ");
  }

  return band.assessed === 0 ? "No dinner service" : null;
}

export function venueSlug(resyUrl: string) {
  return new URL(resyUrl).pathname.split("/").at(-1) ?? resyUrl;
}

/** Friday and Saturday form the weekend supporting signal. */
export function isWeekend(diningDate: string) {
  const weekday = new Date(`${diningDate}T12:00:00Z`).getUTCDay();

  return weekday === 5 || weekday === 6;
}

/** A plain-language reading of the fixed 0–100 scale. */
export function accessTier(score: number) {
  if (score === 100) {
    return "No openings";
  }

  if (score >= 67) {
    return "Scarce";
  }

  if (score >= 34) {
    return "Limited";
  }

  return "Open";
}

export type SortKey = "score" | "name" | "opening" | "weekend";

export type RankedSort = { key: SortKey; descending: boolean };

export const DEFAULT_SORT: RankedSort = { key: "score", descending: true };

const SORT_VALUE: Record<SortKey, (entry: RankedEntry) => number | string> = {
  score: (entry) => entry.score,
  name: (entry) => entry.restaurant.name,
  // No opening within the horizon sorts after every observed date.
  opening: (entry) => entry.nextOpening?.diningDate ?? "9999-12-31",
  weekend: (entry) => entry.restaurant.weekendAvailableDates,
};

/** The first click on a column puts the hardest tables on top. */
export function initialSort(key: SortKey): RankedSort {
  return { key, descending: key === "score" || key === "opening" };
}

export function sortRanked(entries: RankedEntry[], sort: RankedSort): RankedEntry[] {
  const direction = sort.descending ? -1 : 1;
  const value = SORT_VALUE[sort.key];

  return entries.toSorted((a, b) => {
    const left = value(a);
    const right = value(b);

    if (left === right) {
      return byName(a, b);
    }

    return left < right ? -direction : direction;
  });
}

import { ChevronDown, TriangleAlert } from "lucide-react";

import type { RankingData } from "../contract.ts";
import { formatObservedSpan } from "../format.ts";
import { buildRanking } from "../view-model.ts";
import { MethodNotes } from "./method-notes.tsx";
import { RankingTable, UNRANKED_GROUP } from "./ranking-table.tsx";

export function RankingPage({
  data,
  expandedSlug,
  onToggle,
}: {
  data: RankingData;
  expandedSlug: string | undefined;
  onToggle: (slug: string) => void;
}) {
  const ranking = buildRanking(data);
  const observed = formatObservedSpan(ranking.collections);
  const partial = ranking.collections.some((collection) => !collection.discoveryComplete);

  const counts = [
    { title: "Ranked", count: ranking.ranked.length },
    ...ranking.unranked.map((group) => ({
      title: UNRANKED_GROUP[group.standing].title,
      count: group.entries.length,
    })),
  ];

  return (
    <main className="mx-auto max-w-[1240px] px-6 pt-16 pb-24">
      <header className="flex flex-wrap items-end justify-between gap-x-10 gap-y-6">
        <div>
          <p className="text-xs font-medium text-muted-foreground">
            Resy · San Francisco · Party of 2 · 6–9 PM
          </p>
          <h1 className="mt-3 text-5xl leading-none font-semibold tracking-tighter">
            Hardest tables in San Francisco
          </h1>
          <p className="mt-4 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
            {observed ? <span className="tabular">Observed {observed}</span> : null}
            <span className="tabular">{ranking.venueCount} venues</span>
            {partial ? (
              <span className="inline-flex items-center gap-1 text-warn">
                <TriangleAlert className="size-3" />
                Partial listing, not a citywide census
              </span>
            ) : null}
          </p>
        </div>

        <dl className="flex gap-8">
          {counts.map(({ title, count }) => (
            <div key={title}>
              <dt className="text-xs text-muted-foreground">{title}</dt>
              <dd className="mt-1 text-3xl leading-none font-semibold tracking-tight tabular">
                {count}
              </dd>
            </div>
          ))}
        </dl>
      </header>

      <details className="group mt-10 rounded-xl border bg-card">
        <summary className="flex cursor-pointer list-none items-center justify-between rounded-xl px-5 py-3.5 text-sm font-medium focus-visible:outline-2">
          How the score works
          <ChevronDown className="size-4 text-muted-foreground transition-transform group-open:rotate-180 motion-reduce:transition-none" />
        </summary>
        <div className="border-t px-5 py-6">
          <MethodNotes collections={ranking.collections} />
        </div>
      </details>

      <div className="mt-6">
        <RankingTable ranking={ranking} expandedSlug={expandedSlug} onToggle={onToggle} />
      </div>
    </main>
  );
}

import { Fragment, useState } from "react";
import { ArrowDown, ArrowUp } from "lucide-react";
import { cn } from "cn";

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "#/components/ui/table";

import { formatDay, formatScore, formatTime, streetOf } from "../format.ts";
import { DEFAULT_SORT, accessTier, initialSort, sortRanked } from "../view-model.ts";
import type {
  RankedEntry,
  RankedSort,
  Ranking,
  RestaurantEntry,
  SortKey,
  UnrankedEntry,
  UnrankedStanding,
} from "../view-model.ts";
import { WeekStrip } from "./day-status.tsx";
import { RestaurantDetail } from "./restaurant-detail.tsx";
import { BandValue, ScoreBar } from "./score.tsx";

const COLUMN_COUNT = 8;

export const UNRANKED_GROUP: Record<UnrankedStanding, { title: string; note: string }> = {
  unscored: {
    title: "Unscored",
    note: "Regular Resy dinner service, but the headline week has gaps",
  },
  unresolved: {
    title: "Unresolved",
    note: "Evidence cannot tell booked apart from not taking reservations",
  },
  excluded: {
    title: "Excluded",
    note: "Closed, another platform, events or lunch only, or outside SF",
  },
};

export function RankingTable({
  ranking,
  expandedSlug,
  onToggle,
}: {
  ranking: Ranking;
  expandedSlug: string | undefined;
  onToggle: (slug: string) => void;
}) {
  const [sort, setSort] = useState<RankedSort>(DEFAULT_SORT);
  const ranked = sortRanked(ranking.ranked, sort);

  function sortBy(key: SortKey) {
    setSort((current) =>
      current.key === key ? { key, descending: !current.descending } : initialSort(key),
    );
  }

  return (
    <div className="rounded-xl border bg-card">
      <Table className="min-w-[1000px]">
        <TableHeader>
          <TableRow className="text-xs hover:bg-transparent">
            <TableHead className="w-14 pl-5 text-muted-foreground">#</TableHead>
            <SortableHead label="Restaurant" sortKey="name" sort={sort} onSort={sortBy} />
            <SortableHead
              label="Score"
              sortKey="score"
              sort={sort}
              onSort={sortBy}
              className="w-44"
            />
            <TableHead className="w-48 text-muted-foreground">Next 7 dinners</TableHead>
            <TableHead className="w-24 text-right text-muted-foreground">No opening</TableHead>
            <TableHead className="w-32 pl-6 text-muted-foreground">Weeks 2 · 3 · 4</TableHead>
            <SortableHead
              label="Next opening"
              sortKey="opening"
              sort={sort}
              onSort={sortBy}
              className="w-44"
            />
            <SortableHead
              label="Fri/Sat open"
              sortKey="weekend"
              sort={sort}
              onSort={sortBy}
              className="w-28 pr-5 text-right"
            />
          </TableRow>
        </TableHeader>

        <TableBody>
          {ranked.length === 0 ? (
            <TableRow className="hover:bg-transparent">
              <TableCell
                colSpan={COLUMN_COUNT}
                className="px-5 py-10 text-center text-muted-foreground"
              >
                No restaurant has a complete headline week yet.
              </TableCell>
            </TableRow>
          ) : null}
          {ranked.map((entry) => (
            <Fragment key={entry.slug}>
              <RankedRow
                entry={entry}
                expanded={entry.slug === expandedSlug}
                onToggle={() => onToggle(entry.slug)}
              />
              {entry.slug === expandedSlug ? <DetailRow entry={entry} /> : null}
            </Fragment>
          ))}
        </TableBody>

        {ranking.unranked.map((group) => (
          <TableBody key={group.standing}>
            <TableRow className="bg-muted/60 hover:bg-muted/60">
              <TableCell colSpan={COLUMN_COUNT} className="px-5 pt-6 pb-2 text-xs">
                <span className="font-medium">{UNRANKED_GROUP[group.standing].title}</span>
                <span className="ml-2 text-muted-foreground">
                  {UNRANKED_GROUP[group.standing].note}
                </span>
              </TableCell>
            </TableRow>
            {group.entries.map((entry) => (
              <Fragment key={entry.slug}>
                <UnrankedRow
                  entry={entry}
                  expanded={entry.slug === expandedSlug}
                  onToggle={() => onToggle(entry.slug)}
                />
                {entry.slug === expandedSlug ? <DetailRow entry={entry} /> : null}
              </Fragment>
            ))}
          </TableBody>
        ))}
      </Table>
    </div>
  );
}

function SortableHead({
  label,
  sortKey,
  sort,
  onSort,
  className,
}: {
  label: string;
  sortKey: SortKey;
  sort: RankedSort;
  onSort: (key: SortKey) => void;
  className?: string;
}) {
  const active = sort.key === sortKey;
  const direction = sort.descending ? "descending" : "ascending";
  const Arrow = sort.descending ? ArrowDown : ArrowUp;

  return (
    <TableHead
      aria-sort={active ? direction : "none"}
      className={cn("text-muted-foreground", className)}
    >
      <button
        type="button"
        onClick={() => onSort(sortKey)}
        className={cn(
          "inline-flex items-center gap-1 rounded-sm hover:text-foreground focus-visible:outline-2",
          active && "text-foreground",
        )}
      >
        {label}
        {active ? <Arrow className="size-3" /> : null}
      </button>
    </TableHead>
  );
}

function DetailRow({ entry }: { entry: RestaurantEntry }) {
  return (
    <TableRow className="bg-background/60 hover:bg-background/60">
      <TableCell colSpan={COLUMN_COUNT} className="px-5 py-8 whitespace-normal md:px-14">
        <RestaurantDetail entry={entry} />
      </TableCell>
    </TableRow>
  );
}

/** The restaurant name is the row's keyboard control; clicking anywhere on the row also toggles. */
function NameCell({
  entry,
  expanded,
  onToggle,
}: {
  entry: RestaurantEntry;
  expanded: boolean;
  onToggle: () => void;
}) {
  return (
    <TableCell className="py-3.5 pr-4">
      <button
        type="button"
        aria-expanded={expanded}
        onClick={(event) => {
          event.stopPropagation();
          onToggle();
        }}
        className="rounded-sm text-left font-medium focus-visible:outline-2"
      >
        {entry.restaurant.name}
      </button>
      <div className="text-xs text-muted-foreground">{streetOf(entry.restaurant.address)}</div>
    </TableCell>
  );
}

function RankedRow({
  entry,
  expanded,
  onToggle,
}: {
  entry: RankedEntry;
  expanded: boolean;
  onToggle: () => void;
}) {
  const { restaurant, rank, score, nextOpening } = entry;

  return (
    <TableRow onClick={onToggle} className="cursor-pointer" style={{ "--score": score }}>
      <TableCell className="pl-5 font-mono text-xs text-muted-foreground tabular">
        {rank.tied ? "T" : null}
        {rank.position}
      </TableCell>
      <NameCell entry={entry} expanded={expanded} onToggle={onToggle} />
      <TableCell className="pr-6">
        <div className="flex items-baseline gap-2">
          <span className="text-2xl leading-none font-semibold tracking-tight tabular heat-text">
            {formatScore(score)}
          </span>
          <span className="text-[11px] text-muted-foreground">{accessTier(score)}</span>
        </div>
        <ScoreBar score={score} className="mt-2 w-28" />
      </TableCell>
      <TableCell className="pr-6">
        <WeekStrip days={entry.days} />
      </TableCell>
      <TableCell className="text-right tabular">
        {restaurant.unavailable}
        <span className="text-muted-foreground"> / {restaurant.assessed}</span>
        {restaurant.nonService > 0 ? (
          <div className="text-[11px] text-faint">{restaurant.nonService} closed</div>
        ) : null}
      </TableCell>
      <TableCell className="pl-6 font-mono text-xs tabular">
        {entry.bands
          .filter((band) => band.startDay > 1)
          .map((band, index) => (
            <Fragment key={band.startDay}>
              {index > 0 ? <span className="text-faint"> · </span> : null}
              <BandValue band={band} />
            </Fragment>
          ))}
      </TableCell>
      <TableCell className="text-xs tabular">
        {nextOpening ? (
          `${formatDay(nextOpening.diningDate)} · ${formatTime(nextOpening.slot.time)}`
        ) : (
          <span className="text-faint">None in 28 days</span>
        )}
      </TableCell>
      <TableCell className="pr-5 text-right tabular">{restaurant.weekendAvailableDates}</TableCell>
    </TableRow>
  );
}

function UnrankedRow({
  entry,
  expanded,
  onToggle,
}: {
  entry: UnrankedEntry;
  expanded: boolean;
  onToggle: () => void;
}) {
  return (
    <TableRow onClick={onToggle} className="cursor-pointer text-muted-foreground">
      <TableCell className="pl-5 font-mono text-xs text-faint">—</TableCell>
      <NameCell entry={entry} expanded={expanded} onToggle={onToggle} />
      <TableCell className="text-faint">—</TableCell>
      <TableCell className="pr-6">
        {entry.observed ? <WeekStrip days={entry.days} /> : null}
      </TableCell>
      <TableCell colSpan={COLUMN_COUNT - 4} className="pr-5 pl-6 text-xs whitespace-normal">
        {entry.reason}
      </TableCell>
    </TableRow>
  );
}

import { ArrowUpRight, TriangleAlert } from "lucide-react";
import { cn } from "cn";

import { formatDay, formatInterval, formatScore, formatTime, streetOf } from "../format.ts";
import { accessTier, bandGap } from "../view-model.ts";
import type { RestaurantEntry, UnrankedStanding } from "../view-model.ts";
import { DinnerCalendar, StatusLegend } from "./day-status.tsx";

const OPENINGS_SHOWN = 6;

const UNRANKED_TITLE: Record<UnrankedStanding, string> = {
  unscored: "Not scored: the headline week has gaps",
  unresolved: "Unresolved: booked, or not taking reservations?",
  excluded: "Excluded from the ranking",
};

/** Everything behind one row: bands, the 28-day calendar, openings, policy, and evidence. */
export function RestaurantDetail({ entry }: { entry: RestaurantEntry }) {
  const { restaurant } = entry;
  const eligible = restaurant.eligibility === "eligible";

  return (
    <article className="@container space-y-8">
      <header className="flex items-start justify-between gap-6">
        <div className="min-w-0">
          <h2 className="text-3xl font-semibold tracking-tighter">{restaurant.name}</h2>
          <p className="mt-1 text-sm text-muted-foreground">
            {streetOf(restaurant.address)} · Observed{" "}
            {formatInterval(restaurant.observedFrom, restaurant.observedThrough)}
          </p>
        </div>
        {entry.standing === "ranked" ? (
          <div className="text-right" style={{ "--score": entry.score }}>
            <div className="text-6xl leading-none font-semibold tracking-tighter tabular heat-text">
              {formatScore(entry.score)}
            </div>
            <div className="mt-1 text-xs text-muted-foreground">{accessTier(entry.score)}</div>
          </div>
        ) : null}
      </header>

      {entry.standing === "ranked" ? (
        <p className="text-sm text-muted-foreground">
          <span className="text-foreground tabular">
            {restaurant.unavailable} of {restaurant.assessed}
          </span>{" "}
          dinner dates in the next week had no table for two between 6 and 9 PM
          {restaurant.nonService > 0 ? `; ${restaurant.nonService} had no dinner service` : null}.
        </p>
      ) : (
        <div className="flex gap-3 rounded-lg border border-warn/30 bg-warn/5 p-4 text-sm">
          <TriangleAlert className="mt-0.5 size-4 shrink-0 text-warn" />
          <div>
            <div className="font-medium">{UNRANKED_TITLE[entry.standing]}</div>
            <p className="mt-1 text-muted-foreground">{entry.reason}</p>
          </div>
        </div>
      )}

      <div
        className={cn(
          "grid gap-8",
          entry.observed && "@3xl:grid-cols-[minmax(0,1.15fr)_minmax(0,1fr)] @3xl:gap-12",
        )}
      >
        {entry.observed ? (
          <div className="space-y-8">
            {eligible ? (
              <Section title="Seven-day bands">
                <Bands entry={entry} />
              </Section>
            ) : null}
            <Section title="28-day dinner calendar">
              <DinnerCalendar days={entry.days} />
              <StatusLegend />
            </Section>
          </div>
        ) : null}

        <div className="space-y-8">
          {eligible ? (
            <Section title="Openings, party of 2">
              <Openings entry={entry} />
            </Section>
          ) : null}
          {restaurant.bookingPolicy ? (
            <Section title="Booking policy">
              <p className="text-sm leading-relaxed text-muted-foreground">
                {restaurant.bookingPolicy}
              </p>
            </Section>
          ) : null}
          <Section title="Evidence">
            <Evidence entry={entry} />
          </Section>
        </div>
      </div>
    </article>
  );
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="space-y-3">
      <h3 className="text-xs font-medium tracking-wide text-muted-foreground uppercase">{title}</h3>
      {children}
    </section>
  );
}

function Bands({ entry }: { entry: RestaurantEntry }) {
  return (
    <dl className="grid grid-cols-4 overflow-hidden rounded-lg border bg-card">
      {entry.bands.map((band) => (
        <div
          key={band.startDay}
          className={cn("border-l p-3 first:border-l-0", band.startDay === 1 && "bg-muted")}
        >
          <dt className="text-[11px] font-medium whitespace-nowrap text-muted-foreground">
            {band.startDay === 1 ? "Headline" : `Days ${band.startDay}–${band.endDay}`}
          </dt>
          <dd
            className="mt-1 text-2xl font-semibold tracking-tight tabular heat-text"
            style={{ "--score": band.score ?? 0 }}
          >
            {band.score === null ? <span className="text-faint">—</span> : formatScore(band.score)}
          </dd>
          <dd className="mt-0.5 text-[11px] text-faint tabular">
            {band.score === null
              ? bandGap(band)
              : `${band.unavailable}/${band.assessed} no opening`}
          </dd>
        </div>
      ))}
    </dl>
  );
}

function Openings({ entry }: { entry: RestaurantEntry }) {
  const openings = entry.days.flatMap((day) =>
    day.slots.map((slot) => ({ diningDate: day.diningDate, slot })),
  );

  if (openings.length === 0) {
    return (
      <p className="text-sm text-muted-foreground">
        No 6–9 PM table for two was observed in the next 28 days.
      </p>
    );
  }

  return (
    <ul className="divide-y text-sm">
      {openings.slice(0, OPENINGS_SHOWN).map(({ diningDate, slot }) => (
        <li
          key={`${diningDate}-${slot.time}-${slot.type}`}
          className="flex items-baseline gap-3 py-2"
        >
          <span className="w-24 shrink-0 tabular">{formatDay(diningDate)}</span>
          <span className="w-16 shrink-0 font-mono text-xs tabular">{formatTime(slot.time)}</span>
          <span className="min-w-0 flex-1 truncate text-muted-foreground">{slot.type}</span>
          {slot.price ? <span className="text-xs text-faint">{slot.price}</span> : null}
        </li>
      ))}
      {openings.length > OPENINGS_SHOWN ? (
        <li className="py-2 text-xs text-faint">
          +{openings.length - OPENINGS_SHOWN} more openings
        </li>
      ) : null}
    </ul>
  );
}

function Evidence({ entry }: { entry: RestaurantEntry }) {
  return (
    <ul className="space-y-3">
      {entry.restaurant.evidence.map((item) => (
        <li key={`${item.url}-${item.observedAt}`} className="text-sm">
          <blockquote className="border-l-2 pl-3 text-muted-foreground italic">
            “{item.quote}”
          </blockquote>
          <a
            href={item.url}
            target="_blank"
            rel="noreferrer"
            className="mt-1 inline-flex items-center gap-1 pl-3 text-xs text-faint hover:text-foreground"
          >
            {new URL(item.url).hostname}
            <ArrowUpRight className="size-3" />
          </a>
        </li>
      ))}
    </ul>
  );
}

import { cn } from "cn";

