export const STATUS_LABEL: Record<DayStatus, string> = {
  unavailable: "No opening",
  available: "Opening",
  non_service: "No dinner service",
  unreleased: "Not yet released",
  unknown: "Unclear",
  collection_error: "Check failed",
  missing: "Not checked",
};

const LEGEND: DayStatus[] = ["unavailable", "available", "non_service", "unreleased", "unknown"];

export function DayCell({ day, className }: { day: CalendarDay; className?: string }) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span data-status={day.status} className={cn("day-cell", className)}>
          <span className="sr-only">
            {formatDay(day.diningDate)}: {STATUS_LABEL[day.status]}
          </span>
        </span>
      </TooltipTrigger>
      <TooltipContent side="top" className="px-2.5 py-2">
        <div className="font-medium">{formatDay(day.diningDate)}</div>
        <div className="opacity-70">
          {STATUS_LABEL[day.status]} · day {day.offset}
        </div>
        {day.slots.map((slot) => (
          <div key={`${slot.time}-${slot.type}`} className="mt-1 tabular">
            {formatTime(slot.time)} · {slot.type}
            {slot.price ? ` · ${slot.price}` : null}
          </div>
        ))}
      </TooltipContent>
    </Tooltip>
  );
}

/** The headline week, days 1–7. */
export function WeekStrip({ days, className }: { days: CalendarDay[]; className?: string }) {
  return (
    <div className={cn("grid w-40 grid-cols-7 gap-1", className)}>
      {days.slice(0, 7).map((day) => (
        <DayCell key={day.diningDate} day={day} />
      ))}
    </div>
  );
}

/** Days 1–28 as four seven-day bands; columns share a weekday. */
export function DinnerCalendar({ days }: { days: CalendarDay[] }) {
  const weeks = [0, 7, 14, 21].map((start) => days.slice(start, start + 7));

  return (
    <div className="grid max-w-sm grid-cols-[3rem_repeat(7,minmax(0,1fr))] gap-1.5">
      <span />
      {weeks[0].map((day) => (
        <span
          key={day.diningDate}
          className={cn(
            "text-center text-[11px] font-medium text-faint",
            isWeekend(day.diningDate) && "text-foreground",
          )}
        >
          {weekdayLetter(day.diningDate)}
        </span>
      ))}
      {weeks.map((week) => (
        <div key={week[0].diningDate} className="contents">
          <span className="self-center text-[11px] text-faint tabular">
            {week[0].offset}–{week[0].offset + 6}
          </span>
          {week.map((day) => (
            <div key={day.diningDate} className="relative">
              <DayCell day={day} className="w-full" />
              <span className="pointer-events-none absolute top-0.5 left-1 text-[9px] text-white/80 mix-blend-difference tabular">
                {dayOfMonth(day.diningDate)}
              </span>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

export function StatusLegend({ className }: { className?: string }) {
  return (
    <ul
      className={cn(
        "flex flex-wrap items-center gap-x-4 gap-y-2 text-xs text-muted-foreground",
        className,
      )}
    >
      {LEGEND.map((status) => (
        <li key={status} className="flex items-center gap-1.5">
          <span data-status={status} className="day-cell size-3" />
          {STATUS_LABEL[status]}
        </li>
      ))}
    </ul>
  );
}

