function capture(venue: SampleVenue, index: number): RestaurantCapture {
  const resyUrl = `https://resy.com/cities/san-francisco-ca/venues/${venue.slug}`;
  const anchor = localDate(STARTED_AT);
  const eligibility = venue.eligibility ?? "eligible";
  const reason = venue.reason ?? "Regular public dinner reservations for two on Resy";
  // Spread venues across the collection interval, one minute apart.
  const observedAt = new Date(Date.parse(STARTED_AT) + index * 60_000).toISOString();
  const evidence = { url: resyUrl, observedAt, quote: reason };
  const observations: Observation[] = [];

  for (const [offset, code] of (venue.days ?? "").replaceAll(" ", "").split("").entries()) {
    const observation = observationFor(
      code,
      addDays(anchor, offset + 1),
      evidence,
      venue.slots ?? [],
    );

    if (observation) {
      observations.push(observation);
    }
  }

  return {
    name: venue.name,
    resyUrl,
    address: venue.address,
    geography: venue.geography ?? "san_francisco",
    eligibility,
    reason,
    bookingPolicy: venue.bookingPolicy ?? null,
    evidence: [evidence],
    observations,
  };
}

/** Derives the stored record the way import and the `restaurant_ranking` view do. */
function record(restaurant: RestaurantCapture, anchorDate: string): RestaurantRecord {
  const bands = scoreRestaurant(restaurant, anchorDate).map((band) => ({
    collectionId: COLLECTION_ID,
    resyUrl: restaurant.resyUrl,
    startDay: band.startDay,
    endDay: band.endDay,
    available: band.counts.available,
    unavailable: band.counts.unavailable,
    nonService: band.counts.non_service,
    unreleased: band.counts.unreleased,
    unknown: band.counts.unknown,
    collectionError: band.counts.collection_error,
    missing: band.counts.missing,
    assessed: band.assessed,
    score: band.score,
    reason: band.reason,
  }));

  const [headline] = bands;

  const openDates = restaurant.observations
    .flatMap((observation) => (observation.status === "available" ? [observation.diningDate] : []))
    .toSorted();

  return {
    resyUrl: restaurant.resyUrl,
    name: restaurant.name,
    address: restaurant.address,
    collectionId: COLLECTION_ID,
    observedFrom: STARTED_AT,
    observedThrough: FINISHED_AT,
    anchorDate,
    geography: restaurant.geography,
    eligibility: restaurant.eligibility,
    eligibilityReason: restaurant.reason,
    bookingPolicy: restaurant.bookingPolicy,
    score: headline.score,
    scoreReason: headline.reason,
    assessed: headline.assessed,
    available: headline.available,
    unavailable: headline.unavailable,
    nonService: headline.nonService,
    unreleased: headline.unreleased,
    unknown: headline.unknown,
    collectionError: headline.collectionError,
    missing: headline.missing,
    earliestAvailableDate: openDates[0] ?? null,
    weekendAvailableDates: openDates.filter(isWeekend).length,
    evidence: restaurant.evidence,
    bands,
    observations: restaurant.observations,
  };
}

