import { TIME_ZONE, localDate } from "#/scarcity/model.ts";

import type { CollectionSummary } from "./contract.ts";

// Dining dates are SF calendar dates. Format them at UTC noon so server and client agree.
function calendarDate(date: string) {
  return new Date(`${date}T12:00:00Z`);
}

const dayFormat = new Intl.DateTimeFormat("en-US", {
  timeZone: "UTC",
  weekday: "short",
  month: "short",
  day: "numeric",
});

const weekdayFormat = new Intl.DateTimeFormat("en-US", { timeZone: "UTC", weekday: "narrow" });

const clockFormat = new Intl.DateTimeFormat("en-US", {
  timeZone: TIME_ZONE,
  hour: "numeric",
  minute: "2-digit",
});

/** "Tue, Oct 27" */
export function formatDay(date: string) {
  return dayFormat.format(calendarDate(date));
}

/** "T" */
export function weekdayLetter(date: string) {
  return weekdayFormat.format(calendarDate(date));
}

export function dayOfMonth(date: string) {
  return calendarDate(date).getUTCDate();
}

/** "20:45" → "8:45 PM" */
export function formatTime(time: string) {
  const [hours, minutes] = time.split(":").map(Number);
  const suffix = hours >= 12 ? "PM" : "AM";

  return `${hours % 12 || 12}:${minutes.toString().padStart(2, "0")} ${suffix}`;
}

export function formatScore(score: number) {
  return Math.round(score).toString();
}

/** An observation interval in SF time, e.g. "Wed, Sep 30 · 4:00 PM–8:30 PM PT". */
export function formatInterval(from: string, through: string) {
  const fromDate = localDate(from);
  const throughDate = localDate(through);
  const start = `${formatDay(fromDate)} · ${clockFormat.format(new Date(from))}`;

  if (fromDate === throughDate) {
    return `${start}–${clockFormat.format(new Date(through))} PT`;
  }

  return `${start} – ${formatDay(throughDate)} · ${clockFormat.format(new Date(through))} PT`;
}

/** The span covered by every displayed collection. Timestamps are normalized ISO strings. */
export function formatObservedSpan(collections: CollectionSummary[]) {
  const starts = collections.map((collection) => collection.startedAt).toSorted();
  const finishes = collections.map((collection) => collection.finishedAt).toSorted();
  const first = starts[0];
  const last = finishes.at(-1);

  if (!first || !last) {
    return null;
  }

  return formatInterval(first, last);
}

/** The street line of a Resy address. */
export function streetOf(address: string | null) {
  return address?.split(",")[0] ?? "Address unconfirmed";
}

